public class E204 {
    int x, y;
    E204() { this(1, 1); }
    E204(int x, int y) { this.x = x; this.y = y; }
    int area() { return x * y; }
    public static void main(String[] args) {
        E204 a = new E204();
        E204 b = new E204(3, 4);
        System.out.println(a.area() + " " + b.area());
    }
}
